        await sendReq({ url: baseUrl + '/join', method: 'POST', header: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: makeForm({id: userA.id, password: userA.pw, repassword: userA.pw, name: '에이유저', email: userA.email}) });
