        const postMatch = listRes.text().match(/location\.href='\/board_view\/(\d+)'/);
        const otherPostNum = postMatch ? postMatch[1] : '999';
        pm.variables.set('other_post_num', otherPostNum);

        // === [STEP 3] User A의 댓글 작성 및 댓글 번호 추출 ===
        await sendReq({ url: baseUrl + '/board_view', method: 'POST', header: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: makeForm({post_num: otherPostNum, comm_content: 'A유저의 타겟 댓글'}) });
        const viewRes = await sendReq(baseUrl + '/board_view/' + otherPostNum);
        const commMatch = viewRes.text().match(/\/comm_update\/\d+\/(\d+)/);
        const otherCommNum = commMatch ? commMatch[1] : '999';
        pm.variables.set('other_comm_num', otherCommNum);

        console.log(`✅ [1단계 완료] User A 데이터 생성 (글: ${otherPostNum}, 댓글: ${otherCommNum})`);

