        await sendReq(baseUrl + '/logout'); 
        await sendReq({ url: baseUrl + '/join', method: 'POST', header: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: makeForm({id: userB.id, password: userB.pw, repassword: userB.pw, name: '비유저해커', email: userB.email}) });
        await sendReq({ url: baseUrl + '/login', method: 'POST', header: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: makeForm({id: userB.id, password: userB.pw}) });

        console.log(`✅ [2단계 완료] User B(${userB.id}) 세션 덮어쓰기 완료!`);
    } catch (e) {
        console.error("❌ 사전 스크립트 에러:", e);
    }
})();

